createRead.query:
query FlowCreateRead($teamId: String!) {
  team(id: $teamId) {
    createLabels: labels(first: 250) { nodes { id name isGroup parent { name } } }
  }
}

projectByName.query:
query FlowCreateProject($teamId: String!, $name: String!) {
  team(id: $teamId) {
    createProjects: projects(first: 2, filter: { name: { eq: $name } }) { nodes { id name } }
  }
}

projectById.query:
query FlowCreateProjectById($teamId: String!, $id: ID!) {
  team(id: $teamId) {
    createProjects: projects(first: 2, filter: { id: { eq: $id } }) { nodes { id name } }
  }
}

