create.query:
mutation FlowCreateItem($input: IssueCreateInput!) {
  issueCreate(input: $input) { success issue { id identifier url } }
}

createAgain.query:
mutation FlowCreateItem($input: IssueCreateInput!) {
  issueCreate(input: $input) { success issue { id identifier url } }
}

createdRead.query:
query FlowCreatedRead($id: String!) {
  issue(id: $id) { id identifier url archivedAt state { type } team { id key } }
}

